    #[test]
    fn plugin_outcome_validation_codes_are_stable_and_exhaustive() {
        let cases = [
            (
                PluginNodeOutcomeValidationError::InvalidIdentity,
                "invalid_identity",
            ),
            (
                PluginNodeOutcomeValidationError::InvalidExecutor,
                "invalid_executor",
            ),
            (
                PluginNodeOutcomeValidationError::InvalidProposalHash,
                "invalid_proposal_hash",
            ),
            (
                PluginNodeOutcomeValidationError::InvalidSchema,
                "invalid_schema",
            ),
            (
                PluginNodeOutcomeValidationError::InvalidVariableWrite,
                "invalid_variable_write",
            ),
            (
                PluginNodeOutcomeValidationError::InvalidVariableVersion,
                "invalid_variable_version",
            ),
            (
                PluginNodeOutcomeValidationError::InvalidTransition,
                "invalid_transition",
            ),
            (
                PluginNodeOutcomeValidationError::InvalidArtifact,
                "invalid_artifact",
            ),
            (
                PluginNodeOutcomeValidationError::InvalidPreservedState,
                "invalid_preserved_state",
            ),
            (
                PluginNodeOutcomeValidationError::InvalidAction,
                "invalid_action",
            ),
            (
                PluginNodeOutcomeValidationError::PermissionNotDeclared,
                "permission_not_declared",
            ),
            (
                PluginNodeOutcomeValidationError::ExternalEffectProhibited,
                "external_effect_prohibited",
            ),
            (
                PluginNodeOutcomeValidationError::InvalidBudget,
                "invalid_budget",
            ),
            (
                PluginNodeOutcomeValidationError::BudgetExceeded,
                "budget_exceeded",
            ),
        ];

        for (error, expected) in cases {
            assert_eq!(plugin_node_outcome_validation_code(&error), expected);
        }
    }

    fn plugin_action_identity() -> crate::session::PluginNodeInvocationIdentity {
        let declaration_hash = ContentHash::digest(b"plugin-action-declaration");
        crate::session::PluginNodeInvocationIdentity {
            work: NodeWorkIdentity {
                run_id: String::from("run_plugin_action"),
                node_id: String::from("plugin_node"),
                branch_path: Vec::new(),
                attempt: 1,
                loop_iteration: 0,
                step: 2,
            },
            executor: SessionNodeExecutorResolution {
                node_id: String::from("plugin_node"),
                node_kind: String::from("plugin"),
                executor_id: String::from("fixture.plugin-action"),
                executor_version: String::from("1.0.0"),
                source: SessionNodeExecutorSource::Plugin {
                    plugin_id: String::from("fixture.plugin"),
                },
                boundary: SessionNodeExecutorBoundary::PluginHost,
                required_capabilities: vec![String::from("tool.call")],
                resolved_capabilities: vec![String::from("tool.call")],
                runtime_api_requirement: String::from("^1"),
                executor_declaration_hash: declaration_hash,
                adapter_configuration_reference: ContentHash::digest(
                    b"plugin-action-configuration",
                ),
            },
            configuration_hash: ContentHash::digest(b"plugin-action-configuration"),
            plugin_id: String::from("fixture.plugin"),
            invocation_id: String::from("plugin-node:fixture-invocation"),
            invocation_digest: ContentHash::digest(b"plugin invocation"),
            input_hash: ContentHash::digest(b"plugin input"),
            readable_state_hash: ContentHash::digest(b"plugin readable state"),
            causation_event_id: EventId::from_uuid(Uuid::from_u128(0x501)),
        }
    }

    #[test]
    fn plugin_runtime_action_dispatch_is_typed_and_call_id_binds_exact_action() {
        let identity = plugin_action_identity();
        let first = ValidatedPluginRuntimeActionProposal {
            kind: ValidatedPluginActionKind::Tool {
                tool: String::from("filesystem.list"),
            },
            payload: serde_json::json!({
                "tool": "filesystem.list",
                "arguments": {"path": "."}
            }),
            action_hash: ContentHash::digest(b"plugin action one"),
        };
        let proposal = plugin_node_runtime_action(&identity, 0, &first).expect("typed tool action");
        let PluginNodeRuntimeActionProposal::ToolCall {
            call_id,
            tool,
            group,
            arguments,
            source_plugin,
        } = &proposal
        else {
            panic!("tool action")
        };
        assert_eq!(tool, "filesystem.list");
        assert_eq!(group, "filesystem");
        assert_eq!(arguments, &serde_json::json!({"path":"."}));
        assert_eq!(source_plugin, "fixture.plugin");
        assert_eq!(
            plugin_node_runtime_action_tool(&proposal),
            ("filesystem.list", serde_json::json!({"path":"."}))
        );

        let repeated =
            plugin_node_runtime_action(&identity, 0, &first).expect("stable typed tool action");
        assert_eq!(plugin_node_runtime_action_call_id(&repeated), call_id);
        let mut substituted = first;
        substituted.action_hash = ContentHash::digest(b"plugin action substituted");
        let substituted =
            plugin_node_runtime_action(&identity, 0, &substituted).expect("substituted action");
        assert_ne!(plugin_node_runtime_action_call_id(&substituted), call_id);
        assert_ne!(
            plugin_node_runtime_action_proposal_hash(&proposal).expect("proposal hash"),
            plugin_node_runtime_action_proposal_hash(&substituted).expect("substituted hash")
        );
    }

    #[test]
    fn plugin_network_action_maps_only_to_canonical_http_tool() {
        let identity = plugin_action_identity();
        let body_hash = ContentHash::digest(b"request body");
        let action = ValidatedPluginRuntimeActionProposal {
            kind: ValidatedPluginActionKind::Network {
                permission: String::from("api.example.test"),
            },
            payload: serde_json::json!({
                "permission": "api.example.test",
                "method": "POST",
                "url": "https://api.example.test/items",
                "header_names": ["content-type"],
                "body_artifact_reference": "artifact:request-body",
                "body_hash": body_hash.to_hex(),
            }),
            action_hash: ContentHash::digest(b"plugin network action"),
        };
        let proposal =
            plugin_node_runtime_action(&identity, 3, &action).expect("typed network action");
        let (tool, arguments) = plugin_node_runtime_action_tool(&proposal);
        assert_eq!(tool, "http.request");
        assert_eq!(arguments["permission"], "api.example.test");
        assert_eq!(arguments["method"], "POST");
        assert_eq!(arguments["url"], "https://api.example.test/items");
        assert_eq!(arguments["body_hash"], body_hash.to_hex());
    }

    struct ContextReplacingInterceptor;

    #[async_trait]
    impl BlockingInterceptor<ActionProposal> for ContextReplacingInterceptor {
        async fn intercept(
            &self,
            mut proposal: ActionProposal,
        ) -> Result<Decision<ActionProposal>, InterceptorError> {
            proposal.origin = String::from("fixture-replacement");
            Ok(Decision::Replace(proposal))
        }
    }

