    #[test]
    fn parallel_child_graph_approval_validator_rejects_substitution_and_duplicate_paths() {
        let binding = generic_child_wait_binding("user.parallel-child-validator.v1", 10);
        let plan_hash = binding.execution_plan_hash.expect("execution plan hash");
        let plan = binding.execution_plan.as_ref().expect("execution plan");
        let planned = plan
            .nodes
            .iter()
            .find(|resolution| resolution.node_id == "rendezvous")
            .expect("child wait executor");
        let run_id = String::from("validator-run");
        let mut approval = ChildGraphApprovalContinuation {
            session_id: String::from("validator-session"),
            operation: ChildGraphApprovalOperation::CancelChildren,
            run_id: run_id.clone(),
            node_id: String::from("rendezvous"),
            branch_path: vec![String::from("outer"), String::from("exact-branch")],
            attempt: 1,
            loop_iteration: 0,
            step: 7,
            execution_plan_hash: plan_hash,
            adapter_configuration_reference: planned.adapter_configuration_reference,
            request_hash: ContentHash::digest(b"request"),
            subject_hash: ContentHash::digest(b"projection"),
        };
        let continuation_id = child_graph_continuation_id(&approval);
        validate_parallel_child_graph_approval_shape(
            &approval,
            &continuation_id,
            "validator-session",
            &run_id,
            plan_hash,
            planned,
            NativeExecutorKey::ChildWait,
        )
        .expect("exact shape");
        let exact_path = approval.branch_path.clone();
        let region = BTreeSet::from([String::from("rendezvous")]);
        validate_parallel_child_graph_branch_membership(&approval, &exact_path, &region)
            .expect("exact branch membership");

        let mut duplicate_path = approval.clone();
        duplicate_path
            .branch_path
            .push(String::from("exact-branch"));
        assert!(matches!(
            validate_parallel_child_graph_approval_shape(
                &duplicate_path,
                &child_graph_continuation_id(&duplicate_path),
                "validator-session",
                &run_id,
                plan_hash,
                planned,
                NativeExecutorKey::ChildWait,
            ),
            Err(RunTurnError::InvalidContinuationPayload)
        ));

        approval.adapter_configuration_reference = ContentHash::digest(b"substituted");
        assert!(matches!(
            validate_parallel_child_graph_approval_shape(
                &approval,
                &child_graph_continuation_id(&approval),
                "validator-session",
                &run_id,
                plan_hash,
                planned,
                NativeExecutorKey::ChildWait,
            ),
            Err(RunTurnError::InvalidContinuationPayload)
        ));
        approval.adapter_configuration_reference = planned.adapter_configuration_reference;

        let cross_branch = vec![String::from("outer"), String::from("other-branch")];
        assert!(matches!(
            validate_parallel_child_graph_branch_membership(&approval, &cross_branch, &region),
            Err(RunTurnError::InvalidContinuationPayload)
        ));
        let reordered = vec![String::from("exact-branch"), String::from("outer")];
        assert!(matches!(
            validate_parallel_child_graph_branch_membership(&approval, &reordered, &region),
            Err(RunTurnError::InvalidContinuationPayload)
        ));
        assert!(matches!(
            validate_parallel_child_graph_branch_membership(
                &approval,
                &exact_path,
                &BTreeSet::from([String::from("other-node")]),
            ),
            Err(RunTurnError::InvalidContinuationPayload)
        ));
    }

