    #[test]
    fn child_mcp_inheritance_requires_exact_parent_binding_and_mcp_grant() {
        let mut binding = persistent_binding(10);
        binding.tool_groups.push(String::from("mcp"));
        binding.mcp = crate::session::SessionMcpBinding {
            schema_version: 1,
            declaration_hash: ContentHash::digest(b"mcp"),
            configuration_reference: Some(String::from("mcp-bootstrap.enc.json")),
            servers: vec![crate::session::SessionMcpServerBinding {
                id: String::from("fixture"),
                display_name: String::from("Fixture"),
                transport: crate::session::SessionMcpTransportBinding::StreamableHttp {
                    url: String::from("https://localhost.invalid/mcp"),
                    legacy_sse: false,
                    headers: Vec::new(),
                },
            }],
        };
        assert_eq!(
            inherited_child_mcp_binding(&binding, false, &[String::from("mcp")]).expect("disabled"),
            None
        );
        assert_eq!(
            inherited_child_mcp_binding(&binding, true, &[String::from("mcp")])
                .expect("authorized"),
            Some(binding.mcp.clone())
        );
        assert!(matches!(
            inherited_child_mcp_binding(&binding, true, &[]),
            Err(RunTurnError::InvalidChildPolicy)
        ));
        binding.mcp.configuration_reference = None;
        assert!(matches!(
            inherited_child_mcp_binding(&binding, true, &[String::from("mcp")]),
            Err(RunTurnError::InvalidChildPolicy)
        ));
    }

