    fn plugin_automatic_memory_logic(
        data: MockTurnData,
        execution_policy: ProviderExecutionPolicy,
    ) -> TurnLogic<MockTurnData> {
        let runtime = Arc::new(
            crate::plugin_automatic_memory::ProductionPluginAutomaticMemoryWriteTurn::new(
                data.clone(),
            ),
        );
        TurnLogic::new(data, execution_policy).with_plugin_automatic_memory_runtime(runtime)
    }

    fn plugin_context_operation_logic(
        data: MockTurnData,
        execution_policy: ProviderExecutionPolicy,
    ) -> TurnLogic<MockTurnData> {
        let runtime = Arc::new(
            crate::plugin_context_operation::ProductionPluginContextOperationCoordinator::new(
                data.clone(),
            ),
        );
        TurnLogic::new(data, execution_policy)
            .with_plugins(Arc::new(FixturePluginComposition))
            .with_plugin_context_operation_runtime(runtime)
    }

    struct FixturePluginComposition;

    #[async_trait]
    impl crate::plugin::PluginCompositionLogicPort for FixturePluginComposition {
        async fn compose_pipeline(
            &self,
            command: crate::plugin::ComposePluginPipelineCommand,
        ) -> Result<crate::plugin::ComposedPluginPipeline, crate::plugin::PluginCompositionError>
        {
            assert!(
                command
                    .compiled_style
                    .allowed_plugins
                    .contains(&String::from("fixture.plugin"))
            );
            Ok(crate::plugin::ComposedPluginPipeline {
                pipeline: Arc::new(
                    BlockingPipelineBuilder::<crate::action::ActionProposal>::new()
                        .compile()
                        .expect("plugin pipeline"),
                ),
                activated_plugin_ids: vec![String::from("fixture.plugin")],
            })
        }
    }

    fn automatic_memory_ask_policy() -> ProviderExecutionPolicy {
        let mut value = policy(PermissionEffect::Allow);
        value.user_policy = PermissionPolicy::new(
            "user",
            vec![PermissionRule {
                id: String::from("ask-plugin-memory"),
                priority: 100,
                matcher: PermissionMatcher {
                    action: Some(String::from("memory_write")),
                    ..PermissionMatcher::default()
                },
                effect: PermissionEffect::Ask,
                reason: String::from("fixture plugin memory approval"),
            }],
            PermissionEffect::Allow,
            "allow non-memory actions",
        );
        value
    }

    fn session_completion_memory_binding(
        style_id: &str,
        terminal_kind: &str,
    ) -> crate::session::SessionStyleBinding {
        assert!(matches!(terminal_kind, "complete_session" | "fail"));
        let source = format!(
            r#"
format_version = 1
entry = "save-result"
[budget]
max_steps = 4
max_tokens = 1
max_cost_micros = 1
max_duration_ms = 10000
[declarations]
capabilities = ["artifacts"]
providers = []

[[nodes]]
id = "save-result"
kind = "persist_artifact"
configuration = {{ type = "persist_artifact", content = {{ kind = "static_json", value = {{ result = "terminal evidence" }} }}, mime_type = "application/json", security = "private", retention = "session" }}

[[nodes]]
id = "finish"
kind = "{terminal_kind}"

[[edges]]
from = "save-result"
to = "finish"
"#
        );
        let graph = agentmod_graph_engine::compile(
            &source,
            &agentmod_graph_engine::GraphCacheInputs {
                plugin_set_hash: ContentHash::digest(b"plugins"),
                runtime_api_version: String::from("0.1.0"),
                capability_set: BTreeSet::from([String::from("artifacts")]),
            },
            agentmod_graph_engine::CompilerLimits::default(),
        )
        .expect("session-completion memory graph");
        let mut binding = binding(BuiltInStyle::DeclarativeGraph);
        let mut compiled: agentmod_session_style_sdk::CompiledSessionStyle =
            serde_json::from_str(&binding.compiled_style_json).expect("compiled style");
        compiled.style_id = style_id.to_owned();
        compiled.graph = graph;
        binding.id = style_id.to_owned();
        binding.source_locator = format!("fixture:{style_id}");
        binding.compiled_style_json =
            serde_json::to_string(&compiled).expect("compiled serialization");
        binding.compiled_style_hash = ContentHash::digest(binding.compiled_style_json.as_bytes());
        binding.memory.provider = String::from("fixture");
        binding.memory.scopes = vec![String::from("session")];
        binding.memory.write_policy = String::from("session_completion");
        binding.execution_plan = None;
        binding.execution_plan_hash = None;
        crate::node_executor::bind_runtime_execution_plan(
            &agentmod_runtime_data::node_executor::RuntimeNodeExecutorData::native()
                .expect("native registry"),
            &mut binding,
        )
        .expect("session-completion memory execution plan");
        binding
    }

