    #[allow(
        clippy::too_many_lines,
        reason = "the focused production branch-effect fixtures retain a complete arbitrary graph and immutable executor plan"
    )]
    fn generic_parallel_single_effect_binding(
        style_id: &str,
        capability: &str,
        effect_node: &str,
    ) -> crate::session::SessionStyleBinding {
        let declared_capabilities = if capability == "agents" {
            String::from(r#""agents""#)
        } else {
            format!(r#""agents", "{capability}""#)
        };
        let source = r#"
format_version = 1
entry = "fanout"
[budget]
max_steps = 100
max_tokens = 100
max_cost_micros = 100
max_duration_ms = 10000
[declarations]
capabilities = [__CAPABILITIES__]
__DECLARATION__

[[nodes]]
id = "fanout"
kind = "parallel_branch"
configuration = { type = "parallel_branch", max_parallelism = 1, max_queue_depth = 1, join_target = "join", join_policy = "all" }

__EFFECT_NODE__

[[nodes]]
id = "pure"
kind = "conditional_branch"

[[nodes]]
id = "join"
kind = "join_results"
configuration = { type = "join_results", required = ["effect", "pure"], minimum_successes = 2, failure_policy = "fail_fast", ordering_policy = "member_id", timeout_ms = 1000, cancellation_propagates = true, result_projection = "node_references", artifact_collection = "none" }

[[nodes]]
id = "done"
kind = "complete_session"

[[edges]]
from = "fanout"
to = "effect"
label = "effect"

[[edges]]
from = "fanout"
to = "pure"
label = "pure"

[[edges]]
from = "effect"
to = "join"

[[edges]]
from = "pure"
to = "join"

[[edges]]
from = "join"
to = "done"
"#
        .replace(
            "__CAPABILITIES__",
            &declared_capabilities,
        )
        .replace(
            "__DECLARATION__",
            if capability == "tools" {
                r#"tools = ["filesystem.read"]"#
            } else {
                ""
            },
        )
        .replace("__EFFECT_NODE__", effect_node);
        let graph = agentmod_graph_engine::compile(
            &source,
            &agentmod_graph_engine::GraphCacheInputs {
                plugin_set_hash: ContentHash::digest(b"plugins"),
                runtime_api_version: String::from("0.1.0"),
                capability_set: BTreeSet::from([String::from("agents"), capability.to_owned()]),
            },
            agentmod_graph_engine::CompilerLimits::default(),
        )
        .expect("single branch-effect graph");
        let mut binding = binding(BuiltInStyle::DeclarativeGraph);
        let mut compiled: agentmod_session_style_sdk::CompiledSessionStyle =
            serde_json::from_str(&binding.compiled_style_json).expect("compiled style");
        compiled.style_id = style_id.to_owned();
        compiled.graph = graph.clone();
        binding.id = style_id.to_owned();
        binding.source_locator = format!("fixture:{style_id}");
        binding.compiled_style_json =
            serde_json::to_string(&compiled).expect("compiled serialization");
        binding.compiled_style_hash = ContentHash::digest(binding.compiled_style_json.as_bytes());
        bind_native_execution_plan(&mut binding);
        binding
    }

