    async fn run_generic_parallel_direct(
        data: MockTurnData,
        request: RunTurnCommand,
    ) -> Result<RunTurnResult, RunTurnError> {
        run_generic_parallel_direct_with_policy(data, request, policy(PermissionEffect::Allow))
            .await
    }

    async fn run_generic_parallel_direct_with_policy(
        data: MockTurnData,
        request: RunTurnCommand,
        execution_policy: ProviderExecutionPolicy,
    ) -> Result<RunTurnResult, RunTurnError> {
        let selected_session_id =
            SessionId::from_str(&request.session_id).map_err(|_| RunTurnError::InvalidSession)?;
        let session_directory = request.sessions_root.join(&request.session_id);
        let persistence = SessionPersistenceLogic::new(data.clone());
        let preflight = persistence
            .load_session(LoadSessionCommand {
                session_directory: session_directory.clone(),
                expected_session_id: selected_session_id,
            })
            .map_err(RunTurnError::Persistence)?;
        Box::pin(
            TurnLogic::new(data, execution_policy).run_generic_handler_graph(
                request,
                None,
                None,
                selected_session_id,
                session_directory,
                persistence,
                preflight,
            ),
        )
        .await
    }

    async fn run_generic_parallel_with_child_graph_nodes(
        data: MockTurnData,
        request: RunTurnCommand,
        child_graph_nodes: Arc<dyn crate::child_graph_turn::ChildGraphNodeTurnPort>,
    ) -> Result<RunTurnResult, RunTurnError> {
        let selected_session_id =
            SessionId::from_str(&request.session_id).map_err(|_| RunTurnError::InvalidSession)?;
        let session_directory = request.sessions_root.join(&request.session_id);
        let persistence = SessionPersistenceLogic::new(data.clone());
        let preflight = persistence
            .load_session(LoadSessionCommand {
                session_directory: session_directory.clone(),
                expected_session_id: selected_session_id,
            })
            .map_err(RunTurnError::Persistence)?;
        Box::pin(
            TurnLogic::new(data, policy(PermissionEffect::Allow))
                .with_child_graph_nodes(child_graph_nodes)
                .run_generic_handler_graph(
                    request,
                    None,
                    None,
                    selected_session_id,
                    session_directory,
                    persistence,
                    preflight,
                ),
        )
        .await
    }

    fn generic_variable_conditional_binding(style_id: &str) -> crate::session::SessionStyleBinding {
        let mut binding = binding(BuiltInStyle::DeclarativeGraph);
        let mut compiled: agentmod_session_style_sdk::CompiledSessionStyle =
            serde_json::from_str(&binding.compiled_style_json).expect("compiled style");
        let original_branch = compiled
            .graph
            .nodes
            .iter()
            .find(|node| node.kind == agentmod_graph_engine::NodeKind::ConditionalBranch)
            .cloned()
            .expect("conditional");
        let original_edges = compiled
            .graph
            .edges
            .iter()
            .filter(|edge| edge.from == original_branch.index)
            .cloned()
            .collect::<Vec<_>>();
        assert_eq!(original_edges.len(), 2);
        let original_terminal = compiled
            .graph
            .nodes
            .iter()
            .find(|node| node.kind == agentmod_graph_engine::NodeKind::CompleteSession)
            .cloned()
            .expect("terminal");
        let mut branch = original_branch;
        branch.index = 0;
        branch.id = String::from("variable-route");
        let mut request_variable = compiled
            .graph
            .variables
            .iter()
            .find(|variable| variable.name == "request")
            .cloned()
            .expect("request variable");
        request_variable.consumers = BTreeSet::from([branch.id.clone()]);
        let mut approved = original_terminal.clone();
        approved.index = 1;
        approved.id = String::from("approved-terminal");
        let mut denied = original_terminal;
        denied.index = 2;
        denied.id = String::from("denied-terminal");
        denied.kind = agentmod_graph_engine::NodeKind::Fail;
        compiled.style_id = style_id.to_owned();
        compiled.graph.entry_index = 0;
        compiled.graph.nodes = vec![branch, approved, denied];
        compiled.graph.variables = vec![request_variable];
        compiled.graph.edges = original_edges
            .into_iter()
            .enumerate()
            .map(|(index, mut edge)| {
                edge.from = 0;
                edge.to = index + 1;
                edge
            })
            .collect();
        binding.id = style_id.to_owned();
        binding.source_locator = format!("fixture:{style_id}");
        binding.compiled_style_json =
            serde_json::to_string(&compiled).expect("compiled serialization");
        binding.compiled_style_hash = ContentHash::digest(binding.compiled_style_json.as_bytes());
        binding.execution_plan = None;
        binding.execution_plan_hash = None;
        crate::node_executor::bind_runtime_execution_plan(
            &agentmod_runtime_data::node_executor::RuntimeNodeExecutorData::native()
                .expect("native registry"),
            &mut binding,
        )
        .expect("generic variable execution plan");
        binding
    }

