    #[test]
    fn live_typed_summary_plan_is_bounded_and_preserves_declared_input() {
        let mut conversation = crate::conversation::ConversationState::new();
        for index in 1..=24 {
            conversation
                .append(ConversationEntry::UserMessage(text_entry(
                    &format!("user-{index}"),
                    &format!("turn {index}: {}", "context ".repeat(80)),
                    index,
                )))
                .expect("unique history entry");
        }
        let context = CompactionContext {
            projection_id: String::from("summary-boundary"),
            committed_at: Sequence::new(25).expect("sequence"),
        };
        let plan = compact_typed_summary_to_bound(
            &conversation,
            &[String::from("current_input")],
            Some(1_000),
            &context,
        )
        .expect("live typed summary");
        assert_eq!(plan.provenance.method, "summary");
        assert!(plan.replacement.iter().any(|entry| {
            matches!(
                entry,
                ConversationEntry::ContextSummary(summary)
                    if summary.text.contains("agentmod.context-summary.v1")
            )
        }));
        assert!(plan.replacement.iter().any(|entry| {
            matches!(
                entry,
                ConversationEntry::UserMessage(message) if message.id.0 == "user-24"
            )
        }));
        assert!(
            measure_projection(&plan.replacement)
                .expect("measure")
                .estimated_tokens
                <= 1_000
        );
        assert_eq!(conversation.history().len(), 24);
    }

