    #[tokio::test]
    async fn invalid_immutable_tool_configuration_fails_turn_without_result_or_retry() {
        let data = generic_provider_tool_error_data(ToolDataError::InvalidConfiguration);

        let error = TurnLogic::new(data.clone(), policy(PermissionEffect::Allow))
            .run_turn(command())
            .await
            .expect_err("invalid immutable MCP configuration must fail closed");

        assert!(
            matches!(
                error,
                RunTurnError::Tool(ToolExecutionError::InvalidConfiguration)
            ),
            "unexpected error: {error:?}"
        );
        assert_eq!(data.state.tool_execute_calls.load(Ordering::Relaxed), 1);
        assert_eq!(
            data.state.harness_commands.lock().expect("commands").len(),
            1,
            "invalid immutable configuration cannot dispatch a provider continuation"
        );
        assert!(
            !data
                .event_types()
                .iter()
                .any(|event| event == "tool.execution_failed"),
            "invalid immutable configuration cannot become an ordinary tool result"
        );
    }

    #[tokio::test]
