    #[tokio::test]
    #[allow(
        clippy::too_many_lines,
        reason = "the native approval matrix retains exact continuation, substitution, restart, and duplicate evidence"
    )]
    async fn native_automatic_memory_ask_is_restart_safe_and_fail_closed() {
        let mut binding = binding(BuiltInStyle::PersistentChat);
        binding.memory.provider = String::from("fixture");
        binding.memory.scopes = vec![String::from("session")];
        binding.memory.write_policy = String::from("turn_completion");
        let events = vec![data_event(
            1,
            RuntimeCommittedEvent::SessionCreated(SessionCreatedEvent {
                workspace: String::from("fixture-workspace"),
                style: binding.id.clone(),
                style_binding: Some(Box::new(binding)),
            }),
        )];
        let data = MockTurnData::with_scenario(
            events,
            vec![Ok(successful_harness_reply(
                "native-approval-memory-output",
            ))],
            Err(ToolDataError::Unavailable),
        );
        let first = TurnLogic::new(data.clone(), automatic_memory_ask_policy())
            .run_turn(command())
            .await
            .expect("turn waits for native memory approval");
        let continuation_id = first
            .awaiting_continuation
            .expect("durable native automatic-memory approval");
        assert_eq!(data.state.memory_write_calls.load(Ordering::Relaxed), 0);
        let waiting = load_mock_state(&data);
        let record = waiting
            .automatic_memory_writes
            .values()
            .next()
            .expect("proposed native memory write");
        assert!(record.identity.plugin.is_none());
        assert_eq!(
            ContinuationId::from_str(&continuation_id).expect("continuation ID"),
            native_automatic_memory_approval_id(&record.identity.write_id)
        );
        let approval = waiting
            .approvals
            .get(&ContinuationId::from_str(&continuation_id).expect("continuation"))
            .expect("canonical approval request");
        assert!(matches!(
            &approval.subject,
            Some(ApprovalSubject::NativeAutomaticMemoryWrite {
                write_id,
                action_digest,
            }) if write_id == &record.identity.write_id
                && *action_digest == native_automatic_memory_action_proposal(
                    &waiting,
                    &record.identity,
                )
                .expect("native proposal")
                .digest()
                .expect("native digest")
        ));
        let stored = data
            .state
            .continuation
            .lock()
            .expect("continuation")
            .clone()
            .expect("persisted continuation");
        assert!(matches!(
            &stored.payload,
            ContinuationPayloadRecord::NativeAutomaticMemoryWriteApproval(_)
        ));

        let mut substituted = stored.clone();
        let ContinuationPayloadRecord::NativeAutomaticMemoryWriteApproval(payload) =
            &mut substituted.payload
        else {
            unreachable!("native automatic-memory payload was asserted")
        };
        payload.request_hash = ContentHash::digest(b"substituted request");
        *data.state.continuation.lock().expect("continuation") = Some(substituted);
        let before_invalid = data.state.events.lock().expect("events").len();
        let restarted = TurnLogic::new(data.clone(), automatic_memory_ask_policy());
        assert!(matches!(
            restarted
                .resolve_turn_approval(ResolveTurnApprovalCommand {
                    sessions_root: PathBuf::from("sessions"),
                    session_id: session_id().to_string(),
                    continuation_id: continuation_id.clone(),
                    approved: true,
                    resume_after_resolution: true,
                })
                .await,
            Err(RunTurnError::InvalidContinuationPayload)
        ));
        assert_eq!(
            data.state.events.lock().expect("events").len(),
            before_invalid
        );
        *data.state.continuation.lock().expect("continuation") = Some(stored);

        let approved = restarted
            .resolve_turn_approval(ResolveTurnApprovalCommand {
                sessions_root: PathBuf::from("sessions"),
                session_id: session_id().to_string(),
                continuation_id: continuation_id.clone(),
                approved: true,
                resume_after_resolution: true,
            })
            .await
            .expect("native approval resumes after restart");
        assert!(approved.transitioned);
        assert!(approved.awaiting_continuation.is_none());
        assert_eq!(data.state.memory_write_calls.load(Ordering::Relaxed), 1);
        assert!(
            load_mock_state(&data)
                .automatic_memory_writes
                .values()
                .all(|record| record.resume_action() == AutomaticMemoryWriteResumeAction::Complete)
        );
        let before_duplicate = data.state.events.lock().expect("events").len();
        let duplicate = restarted
            .resolve_turn_approval(ResolveTurnApprovalCommand {
                sessions_root: PathBuf::from("sessions"),
                session_id: session_id().to_string(),
                continuation_id,
                approved: true,
                resume_after_resolution: true,
            })
            .await
            .expect("duplicate native approval is idempotent");
        assert!(!duplicate.transitioned);
        assert_eq!(data.state.memory_write_calls.load(Ordering::Relaxed), 1);
        assert_eq!(
            data.state.events.lock().expect("events").len(),
            before_duplicate
        );
    }

