    #[tokio::test]
    #[allow(
        clippy::too_many_lines,
        reason = "one recovery matrix verifies every runtime-owned effect slot against exact terminal receipts"
    )]
    async fn typed_root_effect_slots_commit_after_receipts_and_recover_without_duplicates() {
        let binding = generic_typed_effect_binding("user.typed-effect-graph.v1");
        let data = MockTurnData::with_scenario(
            vec![data_event(
                1,
                RuntimeCommittedEvent::SessionCreated(SessionCreatedEvent {
                    workspace: String::from("fixture-workspace"),
                    style: binding.id.clone(),
                    style_binding: Some(Box::new(binding)),
                }),
            )],
            Vec::new(),
            Ok(style_tool_reply()),
        );
        let request = command();
        let waiting = TurnLogic::new(data.clone(), policy(PermissionEffect::Allow))
            .run_turn(request.clone())
            .await
            .expect("typed effect approval");
        let continuation_id = waiting
            .awaiting_continuation
            .expect("approval continuation");
        TurnLogic::new(data.clone(), policy(PermissionEffect::Allow))
            .resolve_turn_approval(ResolveTurnApprovalCommand {
                sessions_root: PathBuf::from("sessions"),
                session_id: session_id().to_string(),
                continuation_id,
                approved: true,
                resume_after_resolution: true,
            })
            .await
            .unwrap_or_else(|error| {
                panic!(
                    "typed effects complete: {error:?}; {:?}",
                    data.state
                        .events
                        .lock()
                        .expect("events")
                        .iter()
                        .rev()
                        .take(8)
                        .map(|event| (event.metadata.event_type.clone(), event.payload.clone()))
                        .collect::<Vec<_>>()
                )
            });

        let completed = data.state.events.lock().expect("events").clone();
        let assignments = completed
            .iter()
            .filter(|event| event.metadata.event_type == "graph.variable_assigned")
            .map(|event| {
                let payload: RuntimeCommittedEvent =
                    serde_json::from_value(event.payload.clone()).expect("assignment");
                let RuntimeCommittedEvent::VariableAssigned(assigned) = payload else {
                    panic!("variable assignment")
                };
                *assigned
            })
            .collect::<Vec<_>>();
        assert_eq!(assignments.len(), 7);
        assert_eq!(
            assignments
                .iter()
                .find(|assigned| assigned.binding.variable == "approval")
                .expect("approval output")
                .value,
            CanonicalVariableValue::ApprovalResult(CanonicalApprovalResult::Approved)
        );
        for (name, prefix) in [
            ("approval_node", "generic-approval:"),
            ("tool_result", "tool:graph:read:"),
            ("tool_node", "tool:graph:read:"),
            ("artifact", "artifact:blake3:"),
            ("artifact_node", "artifact-persisted"),
            ("event_node", "user-space-event:user.typed_effects:"),
        ] {
            let assigned = assignments
                .iter()
                .find(|assigned| assigned.binding.variable == name)
                .unwrap_or_else(|| panic!("{name} output"));
            let value = match &assigned.value {
                CanonicalVariableValue::ToolResultReference(value)
                | CanonicalVariableValue::NodeResultReference(value)
                | CanonicalVariableValue::ArtifactReference(value) => value.as_str(),
                value => panic!("unexpected {name} output: {value:?}"),
            };
            assert!(
                value.starts_with(prefix),
                "{name} must bind the canonical effect receipt: {assigned:?}"
            );
        }
        let receipt_positions = [
            ("approval.resolved", "approval"),
            ("tool.execution_completed", "tool_result"),
            ("artifact.persistence_completed", "artifact"),
            ("graph.user_space_event_emitted", "event_node"),
        ];
        for (receipt, variable) in receipt_positions {
            let receipt_index = completed
                .iter()
                .position(|event| event.metadata.event_type == receipt)
                .unwrap_or_else(|| panic!("{receipt} receipt"));
            let assignment_index = completed
                .iter()
                .position(|event| {
                    event.metadata.event_type == "graph.variable_assigned"
                        && event.payload.to_string().contains(variable)
                })
                .unwrap_or_else(|| panic!("{variable} assignment"));
            assert!(receipt_index < assignment_index);
        }

        let assignment_cut = completed
            .iter()
            .position(|event| {
                event.metadata.event_type == "graph.variable_assigned"
                    && event.payload.to_string().contains("tool_result")
            })
            .expect("tool assignment cut");
        let recovery = MockTurnData::with_scenario(
            completed[..=assignment_cut].to_vec(),
            Vec::new(),
            Ok(style_tool_reply()),
        );
        TurnLogic::new(recovery.clone(), policy(PermissionEffect::Allow))
            .run_turn(request)
            .await
            .expect("assignment prefix recovers");
        assert_eq!(
            recovery
                .state
                .events
                .lock()
                .expect("events")
                .iter()
                .filter(|event| event.metadata.event_type == "tool.execution_completed")
                .count(),
            1
        );
        assert_eq!(recovery.state.tool_execute_calls.load(Ordering::Relaxed), 0);
        let recovered_assignments = recovery
            .state
            .events
            .lock()
            .expect("events")
            .iter()
            .filter(|event| event.metadata.event_type == "graph.variable_assigned")
            .count();
        assert_eq!(recovered_assignments, 7);
    }

