    #[allow(
        clippy::too_many_lines,
        reason = "the process-shaped regression asserts the complete mixed parallel/join output and canonical merge contract"
    )]
    #[tokio::test]
    async fn admitted_non_builtin_parallel_join_graph_runs_through_normal_turn() {
        let binding = generic_parallel_merged_output_binding("user.parallel.production");
        let executor = CompiledStyleExecutor::from_binding(&binding).expect("executor");
        assert_eq!(executor.adapter_kind(), None);
        assert!(executor.supports_generic_handler_graph());
        let registry = agentmod_runtime_data::node_executor::RuntimeNodeExecutorData::native()
            .expect("registry");
        let records = registry
            .list_node_executors(agentmod_runtime_data::node_executor::ListNodeExecutorsDataRequest)
            .expect("records");
        assert!(["parallel_branch", "join_results"].into_iter().all(|kind| {
            records
                .iter()
                .find(|record| record.node_kind == kind)
                .is_some_and(|record| record.available)
        }));
        let data = MockTurnData::with_events(
            Ok(HarnessDataReply::Events(Vec::new())),
            vec![data_event(
                1,
                RuntimeCommittedEvent::SessionCreated(SessionCreatedEvent {
                    workspace: String::from("fixture-workspace"),
                    style: binding.id.clone(),
                    style_binding: Some(Box::new(binding)),
                }),
            )],
        );
        let result = Box::pin(
            TurnLogic::new(data.clone(), policy(PermissionEffect::Allow)).run_turn(command()),
        )
        .await
        .expect("admitted parallel graph through normal Turn");

        assert!(result.awaiting_continuation.is_none());
        let state = load_mock_state(&data);
        assert_eq!(state.lifecycle, crate::session::SessionLifecycle::Completed);
        let execution = state.style_execution.expect("execution");
        assert_eq!(execution.parallel_executions.len(), 1);
        assert_eq!(execution.generic_joins.len(), 1);
        let joined = execution
            .canonical_variables
            .as_deref()
            .and_then(|variables| {
                variables
                    .environment()
                    .canonical_entries()
                    .get("joined_results")
            })
            .expect("canonical join result");
        assert!(
            matches!(
                &joined.value,
                CanonicalVariableValue::NodeResultReference(reference)
                    if reference.starts_with("join:")
            ),
            "join output must be assigned from the canonical ready decision"
        );
        let shared = execution
            .canonical_variables
            .as_deref()
            .and_then(|variables| variables.environment().canonical_entries().get("shared"))
            .expect("canonical shared merge");
        assert_eq!(shared.version, 1);
        assert!(matches!(
            &shared.value,
            CanonicalVariableValue::NodeResultReference(reference)
                if reference.starts_with("user-space-event:user.parallel.")
        ));
        assert_eq!(
            shared.writer,
            crate::canonical_variables::VariableWriter::Node {
                node_id: String::from("join"),
                branch: None,
            }
        );
        let canonical_events = data
            .state
            .events
            .lock()
            .expect("events")
            .iter()
            .filter_map(|event| {
                serde_json::from_value::<RuntimeCommittedEvent>(event.payload.clone()).ok()
            })
            .collect::<Vec<_>>();
        assert_eq!(
            canonical_events
                .iter()
                .filter(|event| matches!(
                    event,
                    RuntimeCommittedEvent::VariableMerged(merged)
                        if merged.binding.variable == "shared"
                ))
                .count(),
            1
        );
        assert_eq!(
            canonical_events
                .iter()
                .filter(|event| matches!(
                    event,
                    RuntimeCommittedEvent::VariableAssigned(assigned)
                        if assigned.binding.variable == "joined_results"
                ))
                .count(),
            1
        );
        assert_eq!(
            execution
                .completed_nodes
                .iter()
                .map(|completed| completed.node_id.as_str())
                .collect::<Vec<_>>(),
            ["fanout", "join", "done"]
        );
        assert!(
            data.state
                .harness_commands
                .lock()
                .expect("commands")
                .is_empty()
        );
    }

    #[tokio::test]
    #[allow(
        clippy::too_many_lines,
        reason = "the process-like test verifies outbox ordering, pending restart, exact branch payload, approval resume, duplicate resolution, and effect counts as one scenario"
    )]
    async fn non_builtin_parallel_approval_and_artifact_recover_without_duplicate_effects() {
        let binding = generic_parallel_effect_binding("user.parallel.effects");
        let registry = agentmod_runtime_data::node_executor::RuntimeNodeExecutorData::native()
            .expect("registry");
        let records = registry
            .list_node_executors(agentmod_runtime_data::node_executor::ListNodeExecutorsDataRequest)
            .expect("records");
        assert!(["parallel_branch", "join_results"].into_iter().all(|kind| {
            records
                .iter()
                .find(|record| record.node_kind == kind)
                .is_some_and(|record| record.available)
        }));
        let data = MockTurnData::with_events(
            Ok(HarnessDataReply::Events(Vec::new())),
            vec![data_event(
                1,
                RuntimeCommittedEvent::SessionCreated(SessionCreatedEvent {
                    workspace: String::from("fixture-workspace"),
                    style: binding.id.clone(),
                    style_binding: Some(Box::new(binding)),
                }),
            )],
        );

        let waiting = Box::pin(
            TurnLogic::new(data.clone(), policy(PermissionEffect::Allow)).run_turn(command()),
        )
        .await
        .unwrap_or_else(|error| {
            let event_types = data
                .state
                .events
                .lock()
                .expect("events")
                .iter()
                .map(|event| event.metadata.event_type.clone())
                .collect::<Vec<_>>();
            panic!("parallel effects wait for approval: {error}; events={event_types:?}")
        });
        let continuation_id = waiting
            .awaiting_continuation
            .expect("branch approval continuation");
        let first_events = data.state.events.lock().expect("events").clone();
        let dispatch = first_events
            .iter()
            .position(|event| {
                event.metadata.event_type == "graph.parallel_branch_effect_dispatched"
                    && event.payload.to_string().contains("approve-left")
            })
            .expect("approval outbox");
        let requested = first_events
            .iter()
            .position(|event| {
                event.metadata.event_type == "approval.requested"
                    && event.payload.to_string().contains(&continuation_id)
            })
            .expect("approval request");
        assert!(dispatch < requested, "outbox precedes approval request");
        assert_eq!(data.state.artifact_persist_calls.load(Ordering::Relaxed), 1);
        let continuation = data
            .state
            .continuation
            .lock()
            .expect("continuation")
            .clone()
            .expect("stored continuation");
        let ContinuationPayloadRecord::StyleApproval(payload) = continuation.payload else {
            panic!("style approval payload");
        };
        assert_eq!(payload.branch_path.len(), 1);
        assert!(payload.branch_path[0].starts_with("branch:blake3:"));
        assert_eq!(payload.node_id, "approve-left");

        let restarted = Box::pin(
            TurnLogic::new(data.clone(), policy(PermissionEffect::Allow)).run_turn(command()),
        )
        .await
        .expect("pending branch approval recovers");
        assert_eq!(
            restarted.awaiting_continuation.as_deref(),
            Some(continuation_id.as_str())
        );
        assert_eq!(data.state.artifact_persist_calls.load(Ordering::Relaxed), 1);
        assert_eq!(
            data.state
                .events
                .lock()
                .expect("events")
                .iter()
                .filter(|event| event.metadata.event_type == "approval.requested")
                .count(),
            1
        );

        let resolved = TurnLogic::new(data.clone(), policy(PermissionEffect::Allow))
            .resolve_turn_approval(ResolveTurnApprovalCommand {
                sessions_root: PathBuf::from("sessions"),
                session_id: session_id().to_string(),
                continuation_id: continuation_id.clone(),
                approved: true,
                resume_after_resolution: true,
            })
            .await
            .expect("branch approval resumes through parallel recovery");
        assert!(resolved.awaiting_continuation.is_none());
        assert_eq!(data.state.artifact_persist_calls.load(Ordering::Relaxed), 1);
        assert_eq!(
            load_mock_state(&data).lifecycle,
            crate::session::SessionLifecycle::Completed
        );
        let completed_events = data.state.events.lock().expect("events").clone();
        let assignments = completed_events
            .iter()
            .filter(|event| event.metadata.event_type == "graph.variable_assigned")
            .collect::<Vec<_>>();
        assert_eq!(assignments.len(), 2);
        for (variable, expected_node_id) in [
            ("approval_result", "approve-left"),
            ("artifact_result", "artifact-right"),
        ] {
            let assignment = assignments
                .iter()
                .find(|event| event.payload.to_string().contains(variable))
                .unwrap_or_else(|| panic!("{variable} assignment"));
            let payload: RuntimeCommittedEvent =
                serde_json::from_value(assignment.payload.clone()).expect("assignment payload");
            let RuntimeCommittedEvent::VariableAssigned(assigned) = payload else {
                panic!("variable assignment")
            };
            assert!(matches!(
                assigned.writer,
                crate::canonical_variables::VariableWriter::Node {
                    ref node_id,
                    branch: Some(ref branch),
                } if node_id == &assigned.binding.node_id
                    && node_id == expected_node_id
                    && branch.branch_id.starts_with("branch:blake3:")
            ));
            assert_eq!(assigned.binding.node_id, expected_node_id);
        }
        let approval_outcome = completed_events
            .iter()
            .position(|event| {
                event.metadata.event_type == "graph.parallel_branch_effect_outcome_recorded"
                    && event.payload.to_string().contains("approve-left")
            })
            .expect("approval outcome");
        let approval_assignment = completed_events
            .iter()
            .position(|event| {
                event.metadata.event_type == "graph.variable_assigned"
                    && event.payload.to_string().contains("approval_result")
            })
            .expect("approval assignment");
        let approval_completion = completed_events
            .iter()
            .position(|event| {
                event.metadata.event_type == "graph.parallel_branch_node_completed"
                    && event.payload.to_string().contains("approve-left")
            })
            .expect("approval completion");
        let completion_payload: RuntimeCommittedEvent =
            serde_json::from_value(completed_events[approval_completion].payload.clone())
                .expect("approval completion payload");
        let RuntimeCommittedEvent::ParallelBranchNodeCompleted(completed) = completion_payload
        else {
            panic!("parallel branch completion")
        };
        assert_eq!(
            completed.result.inline_value,
            Some(json!({"approval_result":"approved"})),
            "branch transition input must be freshly replayed canonical output"
        );
        assert!(approval_outcome < approval_assignment);
        assert!(approval_assignment < approval_completion);

        let recovery = MockTurnData::with_events(
            Ok(HarnessDataReply::Events(Vec::new())),
            completed_events[..=approval_assignment].to_vec(),
        );
        Box::pin(run_generic_parallel_direct(recovery.clone(), command()))
            .await
            .expect("branch variable receipt prefix recovers without effect redispatch");
        assert_eq!(
            load_mock_state(&recovery).lifecycle,
            crate::session::SessionLifecycle::Completed
        );
        assert_eq!(
            recovery
                .state
                .events
                .lock()
                .expect("events")
                .iter()
                .filter(|event| event.metadata.event_type == "graph.variable_assigned")
                .count(),
            2
        );
        assert_eq!(
            recovery
                .state
                .artifact_persist_calls
                .load(Ordering::Relaxed),
            0
        );

        let duplicate = TurnLogic::new(data.clone(), policy(PermissionEffect::Allow))
            .resolve_turn_approval(ResolveTurnApprovalCommand {
                sessions_root: PathBuf::from("sessions"),
                session_id: session_id().to_string(),
                continuation_id,
                approved: true,
                resume_after_resolution: true,
            })
            .await
            .expect("duplicate approval is idempotent");
        assert!(!duplicate.transitioned);
        assert_eq!(data.state.artifact_persist_calls.load(Ordering::Relaxed), 1);
    }

