    #[tokio::test]
    async fn parallel_tool_approval_rejects_work_branch_executor_and_configuration_substitution() {
        for substitution in ["work", "branch", "executor", "configuration"] {
            let data =
                parallel_tool_data(&format!("user.parallel.tool-substitution.{substitution}"));
            let waiting = Box::pin(run_generic_parallel_direct_with_policy(
                data.clone(),
                command(),
                tool_approval_policy(),
            ))
            .await
            .expect("branch tool asks");
            let continuation_id = waiting.awaiting_continuation.expect("tool approval");
            {
                let mut continuation = data.state.continuation.lock().expect("continuation");
                let ContinuationPayloadRecord::ToolApproval(payload) =
                    &mut continuation.as_mut().expect("stored continuation").payload
                else {
                    panic!("tool approval")
                };
                let identity = payload
                    .generic_graph_identity
                    .as_mut()
                    .expect("generic graph identity");
                match substitution {
                    "work" => identity.node_id = String::from("substituted-node"),
                    "branch" => identity.branch_path = vec![String::from("substituted-branch")],
                    "executor" => identity.executor_id = String::from("runtime.substituted"),
                    "configuration" => {
                        identity.adapter_configuration_reference =
                            ContentHash::digest(b"substituted-configuration");
                    }
                    _ => unreachable!("bounded substitution fixture"),
                }
            }
            let result = TurnLogic::new(data.clone(), tool_approval_policy())
                .resolve_turn_approval(ResolveTurnApprovalCommand {
                    sessions_root: PathBuf::from("sessions"),
                    session_id: session_id().to_string(),
                    continuation_id,
                    approved: true,
                    resume_after_resolution: true,
                })
                .await;
            assert!(
                matches!(result, Err(RunTurnError::InvalidContinuationPayload)),
                "{substitution}: {result:?}"
            );
            assert_eq!(data.state.tool_execute_calls.load(Ordering::Relaxed), 0);
        }
    }

