    #[tokio::test]
    #[allow(
        clippy::too_many_lines,
        reason = "the focused branch proof retains exact executor identity, approval suspension, restart recovery, and one child effect in one scenario"
    )]
    async fn parallel_child_spawn_dispatch_and_restart_recovery_are_exactly_once() {
        let binding = generic_parallel_child_spawn_binding("user.parallel.child-spawn");
        let expected_plan_hash = binding.execution_plan_hash.expect("execution plan hash");
        let expected_resolution = binding
            .execution_plan
            .as_ref()
            .expect("execution plan")
            .nodes
            .iter()
            .find(|resolution| resolution.node_id == "effect")
            .cloned()
            .expect("parallel child executor");
        assert_eq!(expected_resolution.executor_id, "runtime.child-spawn");
        let data = MockTurnData::with_events(
            Err(HarnessDataError::Unavailable),
            vec![data_event(
                1,
                RuntimeCommittedEvent::SessionCreated(SessionCreatedEvent {
                    workspace: String::from("fixture-workspace"),
                    style: binding.id.clone(),
                    style_binding: Some(Box::new(binding)),
                }),
            )],
        );
        let commands = Arc::new(StdMutex::new(Vec::new()));
        let applied = Arc::new(AtomicU64::new(0));
        let port: Arc<dyn crate::child_graph_turn::ChildGraphNodeTurnPort> =
            Arc::new(ApprovalRecordingChildGraphPort {
                data: data.clone(),
                commands: commands.clone(),
                applied: applied.clone(),
                continuation_id: ContinuationId::from_uuid(Uuid::from_u128(0x8181)),
                terminal_ready: None,
            });
        let request = command();

        let waiting = Box::pin(run_generic_parallel_with_child_graph_nodes(
            data.clone(),
            request.clone(),
            port.clone(),
        ))
        .await
        .expect("parallel child approval");
        let continuation_id = waiting
            .awaiting_continuation
            .expect("parallel child approval continuation");
        assert_eq!(applied.load(Ordering::Relaxed), 0);
        let commands_before_restart = commands.lock().expect("commands").len();
        let events_before_restart = data.event_types();

        let restarted = Box::pin(run_generic_parallel_with_child_graph_nodes(
            data.clone(),
            request,
            port.clone(),
        ))
        .await
        .expect("parallel child recovery");
        assert_eq!(
            restarted.awaiting_continuation.as_deref(),
            Some(continuation_id.as_str())
        );
        assert_eq!(applied.load(Ordering::Relaxed), 0);
        assert!(
            commands.lock().expect("commands").len() > commands_before_restart,
            "restart must recover the entered branch through the exact child executor"
        );
        assert_eq!(data.event_types(), events_before_restart);

        let completed = TurnLogic::new(data.clone(), policy(PermissionEffect::Allow))
            .with_child_graph_nodes(port)
            .resolve_turn_approval(ResolveTurnApprovalCommand {
                sessions_root: PathBuf::from("sessions"),
                session_id: session_id().to_string(),
                continuation_id,
                approved: true,
                resume_after_resolution: true,
            })
            .await
            .expect("parallel child resumes");
        assert!(completed.awaiting_continuation.is_none());
        assert_eq!(applied.load(Ordering::Relaxed), 1);

        let commands = commands.lock().expect("commands");
        assert!(!commands.is_empty());
        for executed in commands.iter() {
            assert_eq!(executed.node.execution_plan_hash, expected_plan_hash);
            assert_eq!(executed.node.executor, expected_resolution);
            assert_eq!(executed.node.work.node_id, "effect");
            assert!(
                !executed.node.work.branch_path.is_empty(),
                "parallel child dispatch must retain stable branch identity"
            );
            assert!(matches!(
                executed.node.outcome,
                crate::child_graph_execution::ChildGraphNodeOutcome::Spawn { .. }
            ));
        }
        let state = load_mock_state(&data);
        assert_eq!(state.lifecycle, crate::session::SessionLifecycle::Completed);
        let style_execution = state.style_execution.as_ref().expect("style execution");
        let child_branch = style_execution
            .parallel_executions
            .values()
            .flat_map(|parallel| parallel.branches.values())
            .find(|branch| branch.region.node_ids.contains("effect"))
            .expect("child branch replay");
        assert!(matches!(
            child_branch.control,
            crate::session::ParallelBranchControlState::Terminal {
                disposition: crate::session::ParallelBranchTerminalDisposition::Completed,
                ..
            }
        ));
        assert!(matches!(
            child_branch
                .effect
                .as_ref()
                .and_then(|effect| effect.outcome.as_ref()),
            Some(crate::session::ParallelBranchEffectOutcome::Completed { .. })
        ));
        assert_eq!(
            state
                .child_agents
                .values()
                .filter(|child| child.state == crate::session::ChildAgentState::Active)
                .count(),
            1
        );
    }

