    #[tokio::test]
    async fn parallel_turn_seam_replays_every_restart_prefix_deterministically() {
        let binding = generic_parallel_binding("user.parallel.restart");
        let seed = MockTurnData::with_events(
            Ok(HarnessDataReply::Events(Vec::new())),
            vec![data_event(
                1,
                RuntimeCommittedEvent::SessionCreated(SessionCreatedEvent {
                    workspace: String::from("fixture-workspace"),
                    style: binding.id.clone(),
                    style_binding: Some(Box::new(binding)),
                }),
            )],
        );
        let request = command();
        Box::pin(run_generic_parallel_direct(seed.clone(), request.clone()))
            .await
            .expect("seed parallel run");
        let complete = seed.state.events.lock().expect("events").clone();
        let root_entry = complete
            .iter()
            .position(|event| {
                event.metadata.event_type == "style.node_entered"
                    && event.payload.to_string().contains("fanout")
            })
            .expect("root entry");
        assert_eq!(
            complete
                .last()
                .expect("terminal")
                .metadata
                .event_type
                .as_str(),
            "session.lifecycle_changed"
        );
        for cut in root_entry..complete.len() - 1 {
            let recovery = MockTurnData::with_events_continuing_identity(
                Ok(HarnessDataReply::Events(Vec::new())),
                complete[..=cut].to_vec(),
            );
            Box::pin(run_generic_parallel_direct(
                recovery.clone(),
                request.clone(),
            ))
            .await
            .unwrap_or_else(|error| {
                panic!(
                    "restart cut {cut} ({}) failed: {error}",
                    complete[cut].metadata.event_type
                )
            });
            let recovered_history = recovery.state.events.lock().expect("events").clone();
            if recovered_history != complete {
                let mismatch = recovered_history
                    .iter()
                    .zip(&complete)
                    .position(|(actual, expected)| actual != expected)
                    .unwrap_or_else(|| recovered_history.len().min(complete.len()));
                panic!(
                    "restart cut {cut} changed canonical history at {mismatch}: actual={:?} expected={:?}",
                    recovered_history
                        .get(mismatch)
                        .map(|event| (event.metadata.event_type.as_str(), &event.payload)),
                    complete
                        .get(mismatch)
                        .map(|event| (event.metadata.event_type.as_str(), &event.payload))
                );
            }
            assert!(
                recovery
                    .state
                    .harness_commands
                    .lock()
                    .expect("commands")
                    .is_empty()
            );
        }
    }

    #[allow(
        clippy::too_many_lines,
        reason = "the restart matrix cuts both join output commits and proves exact-history recovery without duplicate writes"
    )]
    #[tokio::test]
    async fn parallel_join_merge_and_result_assignment_recover_each_join_cut_once() {
        let binding = generic_parallel_merged_output_binding("user.parallel.merged-output-restart");
        let seed = MockTurnData::with_events(
            Ok(HarnessDataReply::Events(Vec::new())),
            vec![data_event(
                1,
                RuntimeCommittedEvent::SessionCreated(SessionCreatedEvent {
                    workspace: String::from("fixture-workspace"),
                    style: binding.id.clone(),
                    style_binding: Some(Box::new(binding)),
                }),
            )],
        );
        let request = command();
        Box::pin(run_generic_parallel_direct(seed.clone(), request.clone()))
            .await
            .expect("seed mixed join");
        let complete = seed.state.events.lock().expect("events").clone();
        let canonical = complete
            .iter()
            .map(|event| {
                serde_json::from_value::<RuntimeCommittedEvent>(event.payload.clone())
                    .expect("canonical event")
            })
            .collect::<Vec<_>>();
        let assigned = canonical
            .iter()
            .position(|event| {
                matches!(
                    event,
                    RuntimeCommittedEvent::VariableAssigned(assigned)
                        if assigned.binding.variable == "joined_results"
                )
            })
            .expect("join result assignment");
        let merged = canonical
            .iter()
            .position(|event| {
                matches!(
                    event,
                    RuntimeCommittedEvent::VariableMerged(merged)
                        if merged.binding.variable == "shared"
                )
            })
            .expect("shared merge");
        let completed = canonical
            .iter()
            .position(|event| {
                matches!(
                    event,
                    RuntimeCommittedEvent::StyleNodeCompleted(completed)
                        if completed.node_id == "join"
                )
            })
            .expect("join completion");
        let transitioned = canonical
            .iter()
            .position(|event| {
                matches!(
                    event,
                    RuntimeCommittedEvent::StyleTransitionSelected(transition)
                        if transition.from_node_id == "join"
                )
            })
            .expect("join transition");
        assert!(merged < assigned && assigned < completed && completed < transitioned);

        let run_id = canonical
            .iter()
            .find_map(|event| match event {
                RuntimeCommittedEvent::StyleExecutionInitialized(initialized) => initialized
                    .execution_contract
                    .as_deref()
                    .map(|contract| contract.run_id.clone()),
                _ => None,
            })
            .expect("execution run id");
        let join_entry = canonical
            .iter()
            .find_map(|event| match event {
                RuntimeCommittedEvent::StyleNodeEntered(entered) if entered.node_id == "join" => {
                    Some(entered)
                }
                _ => None,
            })
            .expect("join entry");
        let prior_merge = canonical
            .iter()
            .find_map(|event| match event {
                RuntimeCommittedEvent::VariableMerged(merged)
                    if merged.binding.variable == "shared" =>
                {
                    Some(merged.clone())
                }
                _ => None,
            })
            .expect("prior loop merge");
        let later_work = NodeWorkIdentity {
            run_id,
            node_id: join_entry.node_id.clone(),
            branch_path: Vec::new(),
            attempt: join_entry.attempt,
            loop_iteration: join_entry.loop_iteration + 1,
            step: join_entry.step + 1,
        };
        let later_operation = CoordinatedVariableOperation::Merge {
            variable: prior_merge.binding.variable.clone(),
            expected_version: prior_merge.binding.prior_version,
            branches: prior_merge.branches.clone(),
        };
        assert_eq!(
            TurnLogic::new(seed.clone(), policy(PermissionEffect::Allow))
                .retained_parallel_join_merge(
                    &request.sessions_root.join(&request.session_id),
                    &later_work,
                    "shared",
                    &later_operation,
                )
                .expect("prior-loop merge scan"),
            None,
            "a prior loop's identical merge receipt must not bind later work"
        );

        for cut in [assigned, merged] {
            let recovery = MockTurnData::with_events_continuing_identity(
                Ok(HarnessDataReply::Events(Vec::new())),
                complete[..=cut].to_vec(),
            );
            Box::pin(run_generic_parallel_direct(
                recovery.clone(),
                request.clone(),
            ))
            .await
            .unwrap_or_else(|error| panic!("mixed join cut {cut} failed: {error}"));
            let recovered = recovery.state.events.lock().expect("events").clone();
            assert_eq!(recovered, complete, "mixed join cut {cut} changed history");
            let recovered = recovered
                .iter()
                .map(|event| {
                    serde_json::from_value::<RuntimeCommittedEvent>(event.payload.clone())
                        .expect("recovered event")
                })
                .collect::<Vec<_>>();
            assert_eq!(
                recovered
                    .iter()
                    .filter(|event| matches!(
                        event,
                        RuntimeCommittedEvent::VariableAssigned(assigned)
                            if assigned.binding.variable == "joined_results"
                    ))
                    .count(),
                1
            );
            assert_eq!(
                recovered
                    .iter()
                    .filter(|event| matches!(
                        event,
                        RuntimeCommittedEvent::VariableMerged(merged)
                            if merged.binding.variable == "shared"
                    ))
                    .count(),
                1
            );
        }
    }

