    #[tokio::test]
    #[allow(
        clippy::too_many_lines,
        reason = "one crash-cut test proves creation, duplicate delivery, conflict, and restart replay"
    )]
    async fn nonwaiting_graph_triggers_are_canonical_idempotent_and_restart_safe() {
        let cases = [
            (
                "user.schedule.trigger.once",
                agentmod_graph_engine::ScheduleTrigger::At {
                    timestamp: String::from("1970-01-01T00:00:10Z"),
                },
                None,
            ),
            (
                "user.schedule.trigger.recurring",
                agentmod_graph_engine::ScheduleTrigger::Interval {
                    interval_ms: 1_000,
                    start_timestamp: Some(String::from("1970-01-01T00:00:10Z")),
                },
                None,
            ),
            (
                "user.schedule.trigger.event",
                agentmod_graph_engine::ScheduleTrigger::RuntimeEvent {
                    event_type: String::from("user.ready"),
                },
                Some(ScheduledTriggerObservation::RuntimeEvent {
                    event_id: String::from("event-1"),
                }),
            ),
            (
                "user.schedule.trigger.output",
                agentmod_graph_engine::ScheduleTrigger::ProcessOutput {
                    process_reference: String::from("process-1"),
                    pattern: String::from("READY"),
                },
                Some(ScheduledTriggerObservation::ProcessOutput {
                    output_id: String::from("output-1"),
                }),
            ),
        ];
        for (index, (style, trigger, observation)) in cases.into_iter().enumerate() {
            let binding = generic_schedule_binding(
                style,
                agentmod_graph_engine::NodeConfiguration::Schedule {
                    trigger,
                    wait_for_trigger: false,
                    cancellation: agentmod_graph_engine::ScheduleCancellation::CancelTrigger,
                },
            );
            let data = MockTurnData::with_events(
                Ok(HarnessDataReply::Events(Vec::new())),
                vec![data_event(
                    1,
                    RuntimeCommittedEvent::SessionCreated(SessionCreatedEvent {
                        workspace: String::from("fixture-workspace"),
                        style: binding.id.clone(),
                        style_binding: Some(Box::new(binding)),
                    }),
                )],
            );
            let request = command();
            TurnLogic::new(data.clone(), policy(PermissionEffect::Allow))
                .run_turn(request.clone())
                .await
                .expect("register nonwaiting schedule");
            let record = load_mock_state(&data)
                .style_execution
                .as_ref()
                .and_then(|execution| execution.graph_schedules.values().next())
                .expect("stored schedule")
                .clone();
            let execution_id =
                ContentHash::digest(format!("graph-trigger-{index}").as_bytes()).to_hex();
            let delivery = DeliverGraphScheduleTriggerCommand {
                sessions_root: request.sessions_root.clone(),
                session_id: request.session_id.clone(),
                run_id: record.identity.work.run_id.clone(),
                node_id: record.identity.work.node_id.clone(),
                schedule_id: record.identity.schedule_id.clone(),
                execution_id: execution_id.clone(),
                scheduled_for_ms: 10_000,
                claimed_at_ms: 10_001,
                observation: observation.clone(),
            };
            let logic = TurnLogic::new(data.clone(), policy(PermissionEffect::Allow));
            let first = logic
                .deliver_graph_schedule_trigger(delivery.clone())
                .expect("canonical delivery");
            assert!(first.transitioned);
            let event_count = data.state.events.lock().expect("events").len();
            let duplicate = TurnLogic::new(data.clone(), policy(PermissionEffect::Allow))
                .deliver_graph_schedule_trigger(delivery.clone())
                .expect("restart duplicate");
            assert!(!duplicate.transitioned);
            assert_eq!(duplicate.sequence, first.sequence);
            assert_eq!(data.state.events.lock().expect("events").len(), event_count);
            let mut substituted = delivery;
            substituted.claimed_at_ms = 10_002;
            assert!(matches!(
                logic.deliver_graph_schedule_trigger(substituted),
                Err(RunTurnError::InvalidContinuationPayload)
            ));
            let state = load_mock_state(&data);
            let receipts = &state
                .style_execution
                .as_ref()
                .and_then(|execution| execution.graph_schedules.get(&record.identity.schedule_id))
                .expect("schedule after trigger")
                .trigger_receipts;
            assert_eq!(receipts.len(), 1);
            assert_eq!(receipts[0].execution_id, execution_id);
            assert_eq!(
                data.state
                    .events
                    .lock()
                    .expect("events")
                    .iter()
                    .filter(|event| event.metadata.event_type == "graph.schedule_triggered")
                    .count(),
                1,
                "graph trigger cannot remain a no-op or append twice"
            );
        }
    }

