    #[tokio::test]
    async fn delay_restart_after_dispatch_reconciles_exact_request_and_waits() {
        let binding = generic_schedule_binding(
            "user.delay.dispatch-recovery",
            agentmod_graph_engine::NodeConfiguration::Delay {
                resolution: agentmod_graph_engine::DelayResolution::Duration { duration_ms: 250 },
                expiration_timestamp: Some(String::from("1970-01-01T00:00:10Z")),
                cancellation: agentmod_graph_engine::DelayCancellation::CancelContinuation,
            },
        );
        let seed = MockTurnData::with_events(
            Ok(HarnessDataReply::Events(Vec::new())),
            vec![data_event(
                1,
                RuntimeCommittedEvent::SessionCreated(SessionCreatedEvent {
                    workspace: String::from("fixture-workspace"),
                    style: binding.id.clone(),
                    style_binding: Some(Box::new(binding)),
                }),
            )],
        );
        let request = command();
        TurnLogic::new(seed.clone(), policy(PermissionEffect::Allow))
            .run_turn(request.clone())
            .await
            .expect("seed delay");
        let complete = seed.state.events.lock().expect("events").clone();
        let dispatched = complete
            .iter()
            .position(|event| event.metadata.event_type == "graph.schedule_dispatched")
            .expect("dispatch cut");
        let continuation = seed
            .state
            .continuation
            .lock()
            .expect("continuation")
            .clone()
            .expect("continuation created before dispatch");
        let recovery = MockTurnData::with_events(
            Ok(HarnessDataReply::Events(Vec::new())),
            complete[..=dispatched].to_vec(),
        )
        .with_continuation(continuation);
        let recovered = TurnLogic::new(recovery.clone(), policy(PermissionEffect::Allow))
            .run_turn(request)
            .await
            .expect("reconcile dispatched schedule");
        assert!(recovered.awaiting_continuation.is_some());
        assert_eq!(
            recovery
                .state
                .events
                .lock()
                .expect("events")
                .iter()
                .filter(|event| event.metadata.event_type == "graph.schedule_dispatched")
                .count(),
            1
        );
        assert_eq!(
            recovery
                .state
                .events
                .lock()
                .expect("events")
                .iter()
                .filter(|event| event.metadata.event_type == "graph.schedule_stored")
                .count(),
            1
        );
        assert_eq!(recovery.state.schedules.lock().expect("schedules").len(), 1);
    }

